	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	@Timeout(30)
	void ownerWarmupPublishesAfterDurableRetirementRecovery(boolean unusedValues) throws Exception {
		seedRetirement();
		if (unusedValues) {
			seedPersistedUnusedValue();
		}
		CountDownLatch scanStarted = new CountDownLatch(1);
		CountDownLatch releaseScan = new CountDownLatch(1);
		CountDownLatch ownerAssigned = new CountDownLatch(1);
		AtomicReference<ValueStore> openedValues = new AtomicReference<>();
		AtomicBoolean startedBeforeRecovery = new AtomicBoolean();
		Runnable scanHook = () -> {
			scanStarted.countDown();
			await(ownerAssigned);
			if (startedBeforeRecovery.get()) {
				// Native growth takes the reader lock. Release the scan at actual mutation admission, before that wait.
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
				while (lookupScope(openedValues.get()) != null) {
					assertThat(System.nanoTime()).as("owner must admit its genuine pending recovery write")
							.isLessThan(deadline);
					Thread.onSpinWait();
				}
			} else {
				await(releaseScan);
			}
		};
		LmdbStoreConfig config = config(true);
		StoreProperties properties = new StoreProperties(directory);
		LmdbSailStore owner = new LmdbSailStore(directory, properties, config, false,
				LmdbStoreFormat.fromProperties(properties, config), QueryExecutionPolicy.of(false), scanHook,
				values -> {
					assertThat(values.hasRetiredIds()).as("fixture has legitimate pending owner startup writes")
							.isTrue();
					assertThat(lookupScope(values)).isNotNull();
					openedValues.set(values);
					startedBeforeRecovery.set(values.isValueOverlayWarmupInProgress());
					ownerAssigned.countDown();
					// Synchronize the old scheduled path before owner recovery. Deferred scheduling returns
					// immediately.
					if (startedBeforeRecovery.get()) {
						await(scanStarted);
					}
				});
		try {
			ValueStore values = owner.valueStore();
			assertThat(values.hasRetiredIds()).isFalse();
			assertThat(values.getId(RETIRED)).isEqualTo(LmdbValue.UNKNOWN_ID);
			assertThat(scanStarted.await(10, TimeUnit.SECONDS)).isTrue();
			releaseScan.countDown();
			assertThat(values.awaitValueOverlayReady(10, TimeUnit.SECONDS))
					.as("owner startup writes must finish before automatic overlay snapshot capture")
					.isTrue();
			assertThat(values.compressedValueOverlayStats().records()).isPositive();
			long id = values.getId(KEEPER);
			assertThat(id).isNotEqualTo(LmdbValue.UNKNOWN_ID);
			Boolean overlayHit = values.withData(id, (address, length) -> {
				throw new AssertionError("eligible keeper record must use the populated overlay");
			}, record -> Boolean.TRUE);
			assertThat(overlayHit).isTrue();
		} finally {
			releaseScan.countDown();
			owner.close();
		}
	}

	@Test
	@Timeout(30)
	void failedWarmupStartupClosesItsOwnerResources() throws Exception {
		Properties original = System.getProperties();
		Properties refusingWarmup = new Properties();
		refusingWarmup.putAll(original);
		Properties failing = new Properties(refusingWarmup) {
			@Override
			public String getProperty(String key) {
				if (BUDGET_PROPERTY.equals(key)) {
					throw new SecurityException("controlled warmup property refusal");
				}
				return super.getProperty(key);
			}
		};
		AtomicReference<ValueStore> openedValues = new AtomicReference<>();
		LmdbStoreConfig config = config(true);
		StoreProperties properties = new StoreProperties(directory);
		try {
			assertThatThrownBy(() -> new LmdbSailStore(directory, properties, config, false,
					LmdbStoreFormat.fromProperties(properties, config), QueryExecutionPolicy.of(false), null,
					values -> {
						openedValues.set(values);
						System.setProperties(failing);
					}))
							.isInstanceOf(SecurityException.class)
							.hasMessage("controlled warmup property refusal")
							.hasStackTraceContaining("warmConfiguredValueOverlay");
			assertThatThrownBy(() -> openedValues.get().getTxnManager().createReadTxn())
					.as("failed owner must close its native dictionary")
					.isInstanceOf(IOException.class)
					.hasMessage("Transaction manager is closed");
		} finally {
			System.setProperties(original);
			// Also release the deliberately exposed pre-fix resource when the assertion detects its leak.
			if (openedValues.get() != null) {
				openedValues.get().close();
			}
		}
		LmdbSailStore reopened = new LmdbSailStore(directory, new StoreProperties(directory), config);
		try {
			assertThat(lookupScope(reopened.valueStore())).isNotNull();
		} finally {
			reopened.close();
		}
	}

	@Test
	@Timeout(30)
	void ownerCloseStopsItsWarmupAndReleasesOverlayReservations() throws Exception {
		seedRetirement();
		long retainedBefore = OverlayMemoryBudget.configuredShared().stats().used();
		CountDownLatch scanStarted = new CountDownLatch(1);
		CountDownLatch releaseScan = new CountDownLatch(1);
		LmdbStoreConfig config = config(true);
		StoreProperties properties = new StoreProperties(directory);
		LmdbSailStore owner = new LmdbSailStore(directory, properties, config, false,
				LmdbStoreFormat.fromProperties(properties, config), QueryExecutionPolicy.of(false), () -> {
					scanStarted.countDown();
					await(releaseScan);
				});
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread close = new Thread(() -> {
			try {
				owner.close();
			} catch (Throwable e) {
				failure.set(e);
			}
		}, "owner-overlay-close-test");
		try {
			assertThat(scanStarted.await(10, TimeUnit.SECONDS)).isTrue();
			close.start();
			releaseScan.countDown();
			close.join(TimeUnit.SECONDS.toMillis(10));
			assertThat(close.isAlive()).isFalse();
			assertThat(failure.get()).isNull();
			assertThat(owner.valueStore().isValueOverlayWarmupInProgress()).isFalse();
			assertThat(owner.valueStore().compressedValueOverlayStats()).isNull();
			assertThat(OverlayMemoryBudget.configuredShared().stats().used()).isEqualTo(retainedBefore);
		} finally {
			releaseScan.countDown();
			if (close.getState() == Thread.State.NEW) {
				owner.close();
			} else {
				close.join(TimeUnit.SECONDS.toMillis(10));
			}
		}
	}

	private void seedRetirement() throws Exception {
		LmdbStore store = new LmdbStore(directory, config(false));
		store.init();
		try {
			try (NotifyingSailConnection writer = store.getConnection()) {
				writer.begin();
				writer.addStatement(KEEPER, PREDICATE, VF.createLiteral("kept"));
				writer.addStatement(RETIRED, PREDICATE, VF.createLiteral("removed"));
				writer.commit();
			}
			try (NotifyingSailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				try (var statements = reader.getStatements(RETIRED, PREDICATE, null, false)) {
					assertThat(statements.hasNext()).isTrue();
				}
				try (NotifyingSailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.removeStatements(RETIRED, PREDICATE, null);
					writer.commit();
				}
				assertThat(store.getBackingStore().valueStore().hasRetiredIds()).isTrue();
				reader.commit();
			}
		} finally {
			store.shutDown();
		}
	}

	private LmdbStoreConfig config(boolean overlay) {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false).setValueOverlayEnabled(overlay);
	}

	private void seedPersistedUnusedValue() throws Exception {
		// Standalone dictionary close has no TripleStore liveness checker, so normal GC leaves a durable unused ID.
		ValueStore values = new ValueStore(new File(directory, "values"), new StoreProperties(directory),
				config(false));
		try {
			values.startTransaction(true);
			long id = values.storeValue(VF.createBNode("pending-unused"));
			values.commit();
			values.startTransaction(true);
			values.gcIds(new HashSet<>(Set.of(id)), new HashSet<>());
			values.commit();
		} finally {
			values.close();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			assertThat(latch.await(10, TimeUnit.SECONDS)).as("controlled startup interleaving").isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static Object lookupScope(ValueStore values) {
		try {
			return values.valueLookupScope();
		} catch (IOException e) {
			throw new AssertionError(e);
		}
	}
